# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 245" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="245" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">TERSİNMEZ (TEK YÖNLÜ) VE TERSİNİR (ÇİFT YÖNLÜ) TEPKİMELERİN KARŞILAŞTIRMASI</text>\n  <rect x="20" y="44" width="320" height="184" rx="10" fill="#fee2e2" stroke="#dc2626" stroke-width="2"/>\n  <text x="180" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#991b1b">TERSİNMEZ TEPKİME (A + B → C)</text>\n  <rect x="34" y="78" width="292" height="136" rx="6" fill="#ffffff" stroke="#f87171"/>\n  <text x="180" y="98" text-anchor="middle" font-size="10" font-weight="bold" fill="#b91c1c">Tek Yönlü İlerleme ve Tam Verim</text>\n  <text x="180" y="118" text-anchor="middle" font-size="9.5" fill="#334155">• Tek yönlü ok (→) ile gösterilir.</text>\n  <text x="180" y="136" text-anchor="middle" font-size="9.5" fill="#334155">• Tepkenlerden en az biri tamamen biter ([A] = 0).</text>\n  <text x="180" y="154" text-anchor="middle" font-size="9.5" fill="#334155">• Ürünler tekrar tepkenlere dönüşemez.</text>\n  <text x="180" y="172" text-anchor="middle" font-size="9.5" fill="#334155">• Tepkime sonunda reaksiyon tamamen durur.</text>\n  <text x="180" y="196" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#7f1d1d">Örnek: CH₄(g) + 2O₂(g) → CO₂(g) + 2H₂O(s)</text>\n  <rect x="360" y="44" width="320" height="184" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="520" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">TERSİNİR TEPKİME (X + Y ⇌ Z)</text>\n  <rect x="374" y="78" width="292" height="136" rx="6" fill="#ffffff" stroke="#4ade80"/>\n  <text x="520" y="98" text-anchor="middle" font-size="10" font-weight="bold" fill="#15803d">Çift Yönlü İlerleme ve Dinamik Denge</text>\n  <text x="520" y="118" text-anchor="middle" font-size="9.5" fill="#334155">• Çift yönlü ok (⇌) ile gösterilir.</text>\n  <text x="520" y="136" text-anchor="middle" font-size="9.5" fill="#334155">• Hiçbir madde tamamen tükenmez (%100 verim olmaz).</text>\n  <text x="520" y="154" text-anchor="middle" font-size="9.5" fill="#334155">• İleri ve geri tepkime eş zamanlı devam eder.</text>\n  <text x="520" y="172" text-anchor="middle" font-size="9.5" fill="#334155">• Renk, basınç, pH ve derişimler dengede sabitlenir.</text>\n  <text x="520" y="196" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#14532d">Örnek: N₂O₄(g) (renksiz) ⇌ 2NO₂(g) (kahverengi)</text>\n</svg>', '<svg viewBox="0 0 700 250" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="250" fill="#f8fafc" rx="12"/>\n  <text x="350" y="24" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">DİNAMİK DENGE SÜRECİNDE HIZ - ZAMAN VE DERİŞİM - ZAMAN GRAFİKLERİ</text>\n  <rect x="20" y="40" width="320" height="195" rx="10" fill="#ffffff" stroke="#2563eb" stroke-width="1.8"/>\n  <text x="180" y="60" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e40af">1. TEPKİME HIZI - ZAMAN GRAFİĞİ</text>\n  <line x1="60" y1="205" x2="315" y2="205" stroke="#334155" stroke-width="1.8"/>\n  <line x1="60" y1="205" x2="60" y2="75" stroke="#334155" stroke-width="1.8"/>\n  <text x="52" y="82" text-anchor="end" font-size="9.5" font-weight="bold" fill="#334155">Hız</text>\n  <text x="312" y="220" text-anchor="end" font-size="9.5" font-weight="bold" fill="#334155">Zaman</text>\n  <path d="M 60 85 Q 115 140 185 142 L 305 142" fill="none" stroke="#dc2626" stroke-width="2.5"/>\n  <path d="M 60 205 Q 115 144 185 142 L 305 142" fill="none" stroke="#16a34a" stroke-width="2.5"/>\n  <line x1="185" y1="75" x2="185" y2="205" stroke="#64748b" stroke-width="1.3" stroke-dasharray="4,4"/>\n  <text x="185" y="220" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#475569">t_denge</text>\n  <text x="115" y="102" font-size="9.5" font-weight="bold" fill="#dc2626">r_ileri (azalır)</text>\n  <text x="115" y="190" font-size="9.5" font-weight="bold" fill="#16a34a">r_geri (artar)</text>\n  <text x="245" y="134" text-anchor="middle" font-size="10" font-weight="bold" fill="#1e3a8a">r_ileri = r_geri</text>\n  <rect x="360" y="40" width="320" height="195" rx="10" fill="#ffffff" stroke="#7c3aed" stroke-width="1.8"/>\n  <text x="520" y="60" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#5b21b6">2. DERİŞİM - ZAMAN GRAFİĞİ</text>\n  <line x1="400" y1="205" x2="655" y2="205" stroke="#334155" stroke-width="1.8"/>\n  <line x1="400" y1="205" x2="400" y2="75" stroke="#334155" stroke-width="1.8"/>\n  <text x="394" y="82" text-anchor="end" font-size="9.5" font-weight="bold" fill="#334155">[M]</text>\n  <text x="652" y="220" text-anchor="end" font-size="9.5" font-weight="bold" fill="#334155">Zaman</text>\n  <path d="M 400 85 Q 455 125 525 128 L 645 128" fill="none" stroke="#dc2626" stroke-width="2.5"/>\n  <path d="M 400 205 Q 455 162 525 160 L 645 160" fill="none" stroke="#2563eb" stroke-width="2.5"/>\n  <line x1="525" y1="75" x2="525" y2="205" stroke="#64748b" stroke-width="1.3" stroke-dasharray="4,4"/>\n  <text x="525" y="220" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#475569">t_denge</text>\n  <text x="585" y="120" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#dc2626">[Tepken] = sabit</text>\n  <text x="585" y="152" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#2563eb">[Ürün] = sabit</text>\n  <text x="585" y="185" text-anchor="middle" font-size="9" fill="#475569">(Eşit olmak zorunda değildir!)</text>\n</svg>', '<svg viewBox="0 0 700 225" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="225" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">MİNİMUM ENERJİ VE MAKSİMUM DÜZENSİZLİK EĞİLİMLERİNİN UZLAŞMASI</text>\n  <rect x="30" y="45" width="640" height="55" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="350" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#92400e">Örnek Tepkime:   N₂O₄(g) + ısı (58 kJ)   ⇌   2 NO₂(g)</text>\n  <text x="350" y="88" text-anchor="middle" font-size="10" fill="#78350f">(Girenlerde 1 mol gaz ve ısı var)                         (Ürünlerde 2 mol gaz var)</text>\n  <rect x="30" y="114" width="305" height="92" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="1.8"/>\n  <text x="182" y="136" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e40af">⬅ MİNİMUM ENERJİ EĞİLİMİ</text>\n  <text x="182" y="156" text-anchor="middle" font-size="9.5" fill="#334155">• Daima ısının yazıldığı tarafı destekler.</text>\n  <text x="182" y="174" text-anchor="middle" font-size="9.5" fill="#334155">• Bu tepkime endotermik olduğu için ısı girenlerdedir.</text>\n  <text x="182" y="192" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#1d4ed8">Yönü: Girenler (N₂O₄) lehinedir (⬅)</text>\n  <rect x="365" y="114" width="305" height="92" rx="10" fill="#fce7f3" stroke="#db2777" stroke-width="1.8"/>\n  <text x="517" y="136" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#9d174d">MAKSİMUM DÜZENSİZLİK EĞİLİMİ ➡</text>\n  <text x="517" y="156" text-anchor="middle" font-size="9.5" fill="#334155">• Tanecik serbestliğinin ve gaz mol sayısının</text>\n  <text x="517" y="174" text-anchor="middle" font-size="9.5" fill="#334155">fazla olduğu tarafı (1 mol → 2 mol gaz) destekler.</text>\n  <text x="517" y="192" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#be185d">Yönü: Ürünler (2NO₂) lehinedir (➡)</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
